package com.paytrace.api; import com.paytrace.simulator.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/simulator") public class SimulatorController {private final ScenarioLab lab;public SimulatorController(ScenarioLab lab){this.lab=lab;}@GetMapping("/scenarios") public List<Scenario> scenarios(){return lab.scenarios();}@PostMapping("/runs") public ScenarioRun run(@RequestParam Scenario scenario){return lab.run(scenario);}@GetMapping("/runs/{id}") public Optional<ScenarioRun> get(@PathVariable UUID id){return lab.get(id);}}
